def stamp(g, seq):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    for r in range(1,h-1):
        for c in range(w):
            v=g[r][c]
            if v and v in seq:
                s=c-seq.index(v)
                for k,x in enumerate(seq):
                    cc=s+k
                    if 0<=cc<w: out[r][cc]=x
    return out
